<?php namespace App\Filament\Resources\EmailTemplateResource\Pages; use App\Filament\Resources\EmailTemplateResource; use App\Models\EmailTemplate; use App\Services\EmailTemplateRegistry; use Filament\Resources\Pages\ListRecords; class ListEmailTemplates extends ListRecords { protected static string $resource=EmailTemplateResource::class; public function mount():void{ foreach(app(EmailTemplateRegistry::class)->all() as $key=>$d) EmailTemplate::firstOrCreate(['key'=>$key],['subject'=>$d['subject'],'body'=>$d['body'],'cta_label'=>$d['cta_label']]); parent::mount(); } }
